type ImmediateMDT struct { // [{'type': 'MeasurementsToActivate', 'name': 'measurementsToActivate'}, {'type': 'M1Report', 'name': 'm1report', 'optional': True}, {'type': 'M2Report', 'name': 'm2report', 'optional': True}, None, {'type': 'ProtocolExtensionContainer', 'actual-parameters': ['ImmediateMDT-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}]
    MeasurementsToActivate MeasurementsToActivate
    M1report *M1Report
    M2report *M2Report
    IEExtensions *ImmediateMDTExtIEs
}

func (self * ImmediateMDT) Unpack(stream *Stream) {
    m1report_flag := 0x00000002
    m2report_flag := 0x00000004
    const ext_flag = 0x00000001
    _flags := 0
    _extflags := 0
    _ecount := 0
    _flags = stream.get_flags(3)
    self.MeasurementsToActivate.Unpack(stream)// p8
    if (m1report_flag & _flags) == m1report_flag { //cond2
        self.M1report = &M1Report{}//7{'type': 'M1Report', 'name': 'm1report', 'optional': True}
        self.M1report.Unpack(stream)// p8
    }
    if (m2report_flag & _flags) == m2report_flag { //cond2
        self.M2report = &M2Report{}//7{'type': 'M2Report', 'name': 'm2report', 'optional': True}
        self.M2report.Unpack(stream)// p8
    }
    if (_flags & ext_flag) > 0 {  //iE-Extensions
        _ecount, _extflags = stream.parsef_sequence_ext(1)
    }
    if (_extflags & (1<< 0)) > 0 {
        stream.get_openlen()
        self.IEExtensions = &ImmediateMDTExtIEs{}//7{'type': 'ProtocolExtensionContainer', 'actual-parameters': ['ImmediateMDT-ExtIEs'], 'name': 'iE-Extensions', 'optional': True}
        IEExtensions := ProtocolExtensionContainer {table_ImmediateMDTExtIEs, order_ImmediateMDTExtIEs} // p3
        IEExtensions.Unpack(stream, &self.IEExtensions) // p3
    }
    stream.handle_unknown_ext(_ecount, _extflags, 0, _flags)
    return
}

func (self * ImmediateMDT) Pack(stream *Stream) {
    const m1report_flag uint = 0x00000002
    const m2report_flag uint = 0x00000004
    const ext_flag int = 0x00000001
    const iEExtensions_flag uint = 0x00000001
    _flagReserve := stream.reserve_flags(3)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    self.MeasurementsToActivate.Pack(stream)
    if self.M1report != nil { 
        _flags |= m1report_flag
        self.M1report.Pack(stream)
    }//end of optional
    if self.M2report != nil { 
        _flags |= m2report_flag
        self.M2report.Pack(stream)
    }//end of optional
    if self.IEExtensions != nil { 
        //extension Group: iE-Extensions 1 
        if _extPresent == false {
            stream.set_bits(0, 7)
            _extReserve = stream.reserve_flags(1)
            _extPresent = true
            _flags |= uint(ext_flag)
        }//optind
        _lenOReserve := stream.reserve_flags(8)
        _extflags |= iEExtensions_flag
        IEExtensions := &ProtocolExtensionContainer {table_ImmediateMDTExtIEs, order_ImmediateMDTExtIEs} // p3
        IEExtensions.Pack(stream, &self.IEExtensions)
        stream.set_openlen(_lenOReserve, 8, true)//item
    }//end of optional
    if _extPresent { stream.set_flags(_extflags, _extReserve, 1) }
    stream.set_flags(_flags, _flagReserve, 4)
}//end

type IMSI struct {
  Value HexBytes
}
func (self *IMSI) Unpack(st *Stream) {
    _len := st.parse_olen(3)+3
    if _len < 3 || _len > 8 {
        //fmt.Println ("Invalid len in IMSI")
        return
    }
    self.Value = st.parsef_OctString(_len)
}
func (self *IMSI) Pack(st *Stream) {
    if len(self.Value) < 3 || len(self.Value) > 8 {
        log.Error ("Invalid len in IMSI")
        return
}
    st.format_olen((len(self.Value))-3, 3)
    st.formatf_OctString(self.Value, 0)
}
