func (self *InformationRequested)Unpack(stream *Stream) {
    //coptions := []string{"requestedMBMSIPMulticastAddressandAPNRequest","requestedMulticastServiceList"}
    choice := stream.get_choice(1, 1, 2)
    choice_len := 0
    choice_loc := 0
    if choice >= 2 {
        choice_len = stream.parse_len(0)
        choice_loc = stream.get_location()
        log.Info("Extension choice option [%d] len %d in InformationRequested\n", choice, choice_len)
    }
    if choice == 0 { //ch1
        self.RequestedMBMSIPMulticastAddressandAPNRequest = &RequestedMBMSIPMulticastAddressandAPNRequest{}//cho6
        self.RequestedMBMSIPMulticastAddressandAPNRequest.Unpack(stream)
    } else if choice == 1 { //ch2
        self.RequestedMulticastServiceList = &RequestedMulticastServiceList{}//cho6
        self.RequestedMulticastServiceList.Unpack(stream)
    }//end of if else

    if choice >= 2 {
        stream.set_location(choice_loc, choice_len)
    }
}
func (self * InformationRequested) Pack(stream *Stream) {
    if self.RequestedMBMSIPMulticastAddressandAPNRequest != nil {
        stream.set_choice(0, 1, 1, 2)
        self.RequestedMBMSIPMulticastAddressandAPNRequest.Pack(stream)//2
    } else if self.RequestedMulticastServiceList != nil {
        stream.set_choice(1, 1, 1, 2)
        self.RequestedMulticastServiceList.Pack(stream)//2
    }

}
