func (self *MDTAreaScope)Unpack(stream *Stream) {
    //coptions := []string{"cellbased","labased","rabased","plmn-area-based"}
    choice := stream.get_choice(2, 1, 4)
    choice_len := 0
    choice_loc := 0
    if choice >= 4 {
        choice_len = stream.parse_len(0)
        choice_loc = stream.get_location()
        log.Info("Extension choice option [%d] len %d in MDTAreaScope\n", choice, choice_len)
    }
    if choice == 0 { //ch1
        self.Cellbased = &CellBased{}//cho6
        self.Cellbased.Unpack(stream)
    } else if choice == 1 { //ch2
        self.Labased = &LABased{}//cho6
        self.Labased.Unpack(stream)
    } else if choice == 2 { //ch2
        self.Rabased = &RABased{}//cho6
        self.Rabased.Unpack(stream)
    } else if choice == 3 { //ch2
        var Unpack_plmnareabased = func(st *Stream, self *NULL){
            st.parsef_Null()
        }
        self.Plmnareabased = &NULL{}//cho5
        Unpack_plmnareabased(stream, self.Plmnareabased);
    }//end of if else

    if choice >= 4 {
        stream.set_location(choice_loc, choice_len)
    }
}
func (self * MDTAreaScope) Pack(stream *Stream) {
    if self.Cellbased != nil {
        stream.set_choice(0, 2, 1, 4)
        self.Cellbased.Pack(stream)//2
    } else if self.Labased != nil {
        stream.set_choice(1, 2, 1, 4)
        self.Labased.Pack(stream)//2
    } else if self.Rabased != nil {
        stream.set_choice(2, 2, 1, 4)
        self.Rabased.Pack(stream)//2
    } else if self.Plmnareabased != nil {
        stream.set_choice(3, 2, 1, 4)
        var Pack_plmnareabased = func(st *Stream, self NULL){
            st.formatf_Null()
        }
        Pack_plmnareabased(stream, *self.Plmnareabased)//3
    }

}
